"""Question bank for the adaptive mock interview.

Each question has:
  id, topic, level (Easy/Medium/Hard), q (question text)
  kw     – concept groups. Each group is a list of synonyms; the FIRST entry is the readable
           concept name used when the interviewer probes for something the candidate missed.
  ideal  – a concise model answer shown after the turn
  fu     – trigger-based follow-ups: (list of trigger phrases, follow-up question)
  hint   – a nudge used when the candidate asks for clarification
"""
from typing import Any, Dict, List


def Q(id: str, topic: str, level: str, q: str, kw: List[List[str]], ideal: str,
      fu: List[tuple] = None, hint: str = "") -> Dict[str, Any]:
    return {"id": id, "topic": topic, "level": level, "q": q, "kw": kw, "ideal": ideal,
            "fu": fu or [], "hint": hint}


